{
  "title": "CSCI-633: Biologically Inspired Intelligent Systems - Foundations Lesson",
  "learningObjectives": [
    "Define the core components of the NIST AI Risk Management Framework and explain how each phase addresses AI deployment risks.",
    "Explain how machine-learning workflows prevent data leakage and ensure consistent preprocessing through pipeline construction.",
    "Identify how biologically inspired computational models leverage principles from neuroscience and cognitive science to solve complex problems."
  ],
  "beats": [
    {
      "title": "Course Context and Scope",
      "claim": "CSCI-633 focuses on developing computational models that are biologically inspired to solve complex problems, drawing on advances in neuroscience, cognitive science, and physiology",
      "example": "Students will explore how artificial neural networks mimic biological neural networks to process information",
      "visualDirection": "Display a side-by-side diagram comparing biological neurons with artificial neural network layers, highlighting input processing, integration, and output transmission",
      "sourceIds": ["rit-csci-633"]
    },
    {
      "title": "Prerequisites and Course Requirements",
      "claim": "Students must complete prerequisite courses such as CSCI-603, CSCI-605, and CSCI-661 with grades of B or better, or equivalent combinations",
      "example": "A student with CSCI-243 and CSCI-262 can satisfy the prerequisite requirement through the alternative pathway",
      "visualDirection": "Show a flowchart mapping the three prerequisite pathways to the CSCI-633 course entry point, using color-coded arrows to indicate valid routes",
      "sourceIds": ["rit-csci-633"]
    },
    {
      "title": "NIST Framework Governance Phase",
      "claim": "The Govern phase establishes policies, responsibilities, and accountability for AI risk within an organization",
      "example": "A company might assign a dedicated AI ethics board to oversee model development and deployment decisions",
      "visualDirection": "Create a table listing key governance responsibilities such as policy formulation, role assignment, and accountability tracking",
      "sourceIds": ["nist-ai-rmf"]
    },
    {
      "title": "NIST Framework Mapping Phase",
      "claim": "The Map phase documents context, intended use, affected people, and potential impacts before deployment",
      "example": "Developers would record how a facial recognition system might affect privacy rights and identify specific user demographics",
      "visualDirection": "Illustrate a risk mapping template with fields for context description, intended use cases, affected populations, and potential impact categories",
      "sourceIds": ["nist-ai-rmf"]
    },
    {
      "title": "NIST Framework Measurement Phase",
      "claim": "The Measure phase uses qualitative and quantitative methods to analyze identified risks and assess system robustness",
      "example": "Researchers might conduct user interviews to gather qualitative feedback while running statistical tests to measure model accuracy and fairness",
      "visualDirection": "Present a split-screen graphic showing qualitative methods like survey responses alongside quantitative metrics such as accuracy charts and bias indicators",
      "sourceIds": ["nist-ai-rmf"]
    },
    {
      "title": "NIST Framework Management Phase",
      "claim": "The Manage phase prioritizes risks and allocates resources for response and monitoring after deployment",
      "example": "An organization might schedule quarterly model audits and maintain a risk response playbook for emerging vulnerabilities",
      "visualDirection": "Design a risk prioritization matrix with axes for likelihood and impact, showing how resources are allocated to high-risk items",
      "sourceIds": ["nist-ai-rmf"]
    },
    {
      "title": "Machine Learning Workflow Structure",
      "claim": "Machine-learning workflows separate data preparation, training, validation, testing, model selection, and evaluation to ensure rigorous analysis",
      "example": "A developer would first clean and normalize data, then split it into training and testing sets before training the model",
      "visualDirection": "Draw a linear pipeline diagram showing each workflow stage as a connected block, with arrows indicating data flow from preparation to evaluation",
      "sourceIds": ["scikit-learn-user-guide"]
    },
    {
      "title": "Preprocessing and Pipeline Construction",
      "claim": "Pipelines combine preprocessing and estimators so the same transformations are applied consistently across training and testing data",
      "example": "A pipeline might apply standardization to numerical features and encoding to categorical features before passing data to the classifier",
      "visualDirection": "Show a pipeline object structure with nested components, highlighting how preprocessing steps are bundled with the model estimator",
      "sourceIds": ["scikit-learn-user-guide"]
    },
    {
      "title": "Evaluation and Leakage Prevention",
      "claim": "Preprocessing must be fitted only on permitted training data to avoid leakage, and evaluation metrics must match the task and the cost of different errors",
      "example": "Using test data to scale features would leak information, so developers must fit scalers exclusively on training samples",
      "visualDirection": "Illustrate a data split diagram with training and testing sets, showing preprocessing fitting on training data only and evaluation metrics displayed on testing data",
      "sourceIds": ["scikit-learn-user-guide"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "Valid results require checking for leakage, distribution shift, overfitting, and unexamined assumptions while maintaining separate hyperparameter selection from final test",
      "example": "A developer would verify that cross-validation splits prevent data leakage and that hyperparameter tuning uses only validation data",
      "visualDirection": "List a concise checklist with checkboxes for verifying data isolation, monitoring distribution shifts, checking for overfitting, and confirming hyperparameter separation",
      "sourceIds": ["scikit-learn-user-guide"]
    }
  ]
}
